import faiss
import numpy as np
import pickle
from sentence_transformers import SentenceTransformer

# Modelo para embeddings
embedding_model = SentenceTransformer("Qwen/Qwen2.5-1.5B")

# Exemplo de documentos (pode carregar de um CSV, banco de dados, etc.)
